<script setup lang="ts">
import { ArrowLeft, ChevronDown, ChevronUp, Eye, FileText, Info, Plus, Save, Trash2, X } from 'lucide-vue-next'
import { computed, onMounted, reactive, ref } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import PageContainer from '@/components/shared/PageContainer.vue'
import PageHeader from '@/components/shared/PageHeader.vue'
import { Badge } from '@/components/ui/badge'
import { Button } from '@/components/ui/button'
import { Input } from '@/components/ui/input'
import { createQuotationsService, type MasterOptions } from '@/services/api/quotations'
import type { TransportQuotationDoc } from '@/types/quotations'
import MasterCombobox from './components/MasterCombobox.vue'
import LocationMultiSelect from './components/LocationMultiSelect.vue'
import TomSelectField from './components/TomSelectField.vue'

const route = useRoute(); const router = useRouter(); const api = createQuotationsService()
const editing = computed(() => typeof route.params.id === 'string' && route.params.id !== 'new')
const form = reactive<TransportQuotationDoc>({ quotation_date: new Date().toISOString().slice(0, 10), customer: '', valid_until: '', currency: 'AED', status: 'Draft', materials: [], locations: [], rates: [], estimated_quantity: '', estimated_trips: '', customer_reference: '', service_period_from: '', service_period_to: '', customer_approval_date: '', customer_approval_reference: '', customer_approval_notes: '', remarks: '' })
const canEdit = computed(() => !editing.value || form.status === 'Draft')
const busy = ref(false); const loadingMasters = ref(false); const error = ref(''); const saved = ref(''); const previewOpen = ref(false); const estimateOpen = ref(false); const selectedMaterial = ref(''); const expanded = ref<Record<string, boolean>>({}); const masterLoading = reactive({ customers: false, materials: false, locations: false })
const masters = ref<MasterOptions>({ customers: [], materials: [], locations: [] })
const completion = computed(() => { const missing = form.materials.reduce((total, material) => total + (selectedLocations(material.material, 'Loading').length ? 0 : 1) + (selectedLocations(material.material, 'Destination').length ? 0 : 1), 0); return { missing, ready: form.materials.length > 0 && missing === 0 } })
const summary = computed(() => completion.value.ready ? `${form.materials.length} material${form.materials.length === 1 ? '' : 's'} ready for rate coverage` : `${form.materials.length} material${form.materials.length === 1 ? '' : 's'} · ${completion.value.missing} location requirement${completion.value.missing === 1 ? '' : 's'} pending`)
function selectedLocations(material: string, role: 'Loading' | 'Destination') { return form.locations.filter((row) => row.material === material && row.location_role === role).map((row) => row.location) }
function setLocations(material: string, role: 'Loading' | 'Destination', values: string[]) { form.locations = form.locations.filter((row) => row.material !== material || row.location_role !== role); form.locations.push(...values.map((location) => ({ material, location_role: role, location }))) }
function toggleMaterial(material: string) { expanded.value[material] = !expanded.value[material] }
function addMaterial() { const value = selectedMaterial.value.trim(); if (!value || form.materials.some((row) => row.material === value)) return; form.materials.push({ material: value }); expanded.value[value] = true; selectedMaterial.value = '' }
function focusMaterialPicker() { (document.querySelector('input[placeholder="Search materials…"]') as HTMLInputElement | null)?.focus() }
function createNewCustomer() { window.open('/app/customer/new', '_blank', 'noopener') }
function removeMaterial(material: string) { const hasRates = form.rates.some((row) => row.material === material); if (hasRates && !window.confirm('Remove this material and its associated unsaved rate rows?')) return; form.materials = form.materials.filter((row) => row.material !== material); form.locations = form.locations.filter((row) => row.material !== material); form.rates = form.rates.filter((row) => row.material !== material) }
function locationsForRate(material: string, role: 'Loading' | 'Destination') { return form.locations.filter((row) => row.material === material && row.location_role === role) }
function addRate() { const material = form.materials[0]?.material; if (!material) return; form.rates.push({ material, loading_location: locationsForRate(material, 'Loading')[0]?.location ?? '', unloading_location: locationsForRate(material, 'Destination')[0]?.location ?? '', rate: '', effective_from: form.service_period_from ?? '', effective_to: form.service_period_to ?? '' }) }
function removeRate(index: number) { form.rates.splice(index, 1) }
function rateOverlap(index: number) { const row = form.rates[index]; if (!row?.effective_from || !row.effective_to) return false; return form.rates.some((other, otherIndex) => otherIndex !== index && other.material === row.material && other.loading_location === row.loading_location && other.unloading_location === row.unloading_location && row.effective_from <= other.effective_to && row.effective_to >= other.effective_from) }
async function searchCustomers(query: string) { masterLoading.customers = true; try { masters.value.customers = await api.searchCustomers(query) } catch (e) { error.value = e instanceof Error ? e.message : 'Unable to load customers.' } finally { masterLoading.customers = false } }
async function searchMaterials(query: string) { masterLoading.materials = true; try { masters.value.materials = await api.searchMaterials(query) } catch (e) { error.value = e instanceof Error ? e.message : 'Unable to load materials.' } finally { masterLoading.materials = false } }
async function searchLocations(query: string, role?: 'Loading' | 'Destination') { masterLoading.locations = true; try { const results = await api.searchLocations(query, role); const merged = [...masters.value.locations, ...results]; masters.value.locations = merged.filter((item, index, list) => list.findIndex((candidate) => candidate.name === item.name) === index) } catch (e) { error.value = e instanceof Error ? e.message : 'Unable to load locations.' } finally { masterLoading.locations = false } }
async function load() { loadingMasters.value = true; error.value = ''; try { await Promise.all([searchCustomers(''), searchMaterials(''), searchLocations('')]); if (editing.value) Object.assign(form, await api.getQuotation(route.params.id as string)); form.materials.forEach((row) => { expanded.value[row.material] = true }) } catch (e) { error.value = e instanceof Error ? e.message : 'Unable to load quotation data.' } finally { loadingMasters.value = false } }
function validateForm(submit: boolean) { if (!form.customer || !form.quotation_date || !form.valid_until) throw new Error('Customer, quotation date and valid until are required.'); if (Boolean(form.service_period_from) !== Boolean(form.service_period_to)) throw new Error('Enter both service period dates or leave both blank.'); if (form.materials.some((row) => !row.material) || new Set(form.materials.map((row) => row.material)).size !== form.materials.length) throw new Error('Complete each material and do not repeat a material.'); if (form.locations.some((row) => !row.material || !row.location)) throw new Error('Complete each location selection.'); if (form.rates.some((row, index) => !row.material || !row.loading_location || !row.unloading_location || !row.effective_from || !row.effective_to || Number(row.rate) <= 0 || rateOverlap(index))) throw new Error('Complete each rate row with a positive, non-overlapping effective period.'); if (submit && (!completion.value.ready || !form.rates.length || !form.customer_approval_date)) throw new Error('Approval requires customer approval date, material coverage, and at least one complete rate.') }
function payload(): TransportQuotationDoc { return JSON.parse(JSON.stringify(form)) as TransportQuotationDoc }
async function save(submit = false) { if (!canEdit.value || busy.value) return; busy.value = true; error.value = ''; saved.value = ''; try { validateForm(submit); const doc = payload(); const result = editing.value ? await api.update(route.params.id as string, doc) : await api.create(doc); const final = submit ? await api.submit(result) : result; saved.value = submit ? 'Quotation approved.' : 'Draft saved.'; await router.replace(`/quotations/${encodeURIComponent(final.name ?? route.params.id as string)}`) } catch (e) { error.value = e instanceof Error ? e.message : 'Unable to save quotation.' } finally { busy.value = false } }
onMounted(() => { void load() })
</script>

<template>
  <PageContainer class="pb-28">
    <PageHeader :title="editing ? `Edit ${route.params.id}` : 'New Transport Quotation'" subtitle="Customer rates, service period and approval record.">
      <template #actions><Button variant="outline" @click="router.push('/quotations')"><ArrowLeft /> Back</Button><Badge variant="muted">{{ form.status }}</Badge><Button v-if="canEdit" :disabled="busy" @click="save()"><Save /> Save draft</Button><Button v-if="canEdit && form.status === 'Draft'" :disabled="busy" @click="save(true)">Approve quotation</Button></template>
    </PageHeader>
    <div v-if="error" class="mb-4 flex items-start justify-between gap-3 rounded-lg border border-destructive/30 bg-destructive/5 p-3 text-sm text-destructive"><span>{{ error }}</span><button aria-label="Dismiss error" @click="error = ''"><X class="size-4" /></button></div>
    <div v-if="saved" class="mb-4 rounded-lg border border-emerald-200 bg-emerald-50 p-3 text-sm text-emerald-700">{{ saved }}</div>
    <fieldset :disabled="!canEdit" class="space-y-5">
      <section class="rounded-xl border bg-card p-5 shadow-sm"><div class="mb-5 flex items-start justify-between"><div><h2 class="text-lg font-bold">Quotation information</h2><p class="text-sm text-muted-foreground">Number is generated by Frappe · currency is fixed to AED.</p></div><Badge variant="muted">{{ form.status }}</Badge></div><div class="grid gap-4 md:grid-cols-2 lg:grid-cols-3">
        <label class="field">Quotation number<div class="control flex items-center justify-between bg-muted/40 text-muted-foreground">{{ form.name || 'Auto-generated on save' }}<FileText class="size-4" /></div></label>
        <label class="field">Customer *<TomSelectField v-model="form.customer" :options="masters.customers" placeholder="Search customers…" :loading="masterLoading.customers" :disabled="!canEdit" allow-create @search="searchCustomers" @create-new="createNewCustomer" /></label>
        <label class="field">Quotation date *<Input v-model="form.quotation_date" type="date" /></label><label class="field">Valid until *<Input v-model="form.valid_until" type="date" /></label>
        <label class="field">Service period from<Input v-model="form.service_period_from" type="date" /></label><label class="field">Service period to<Input v-model="form.service_period_to" type="date" /></label>
        <label class="field">Customer reference<Input v-model="form.customer_reference" placeholder="PO / email reference — optional" /></label><label class="field md:col-span-2">Remarks<textarea v-model="form.remarks" class="control min-h-20" placeholder="Optional notes for the customer…" /></label>
      </div></section>
      <section class="rounded-xl border bg-card p-5 shadow-sm"><div class="mb-4 flex flex-wrap items-start justify-between gap-3"><div><div class="flex items-center gap-3"><h2 class="text-lg font-bold">Transportation materials</h2><Badge variant="muted">{{ form.materials.length }}</Badge></div><p class="text-sm text-muted-foreground">Each material carries its own loading points, destinations and rates.</p></div><div class="flex w-full gap-2 sm:w-auto"><MasterCombobox v-model="selectedMaterial" :options="masters.materials" placeholder="Search materials…" :loading="masterLoading.materials" @search="searchMaterials" /><Button :disabled="!selectedMaterial" @click="addMaterial"><Plus /> Add material</Button></div></div>
        <div v-if="!form.materials.length" class="rounded-lg border border-dashed bg-muted/20 p-12 text-center"><div class="mx-auto mb-3 flex size-12 items-center justify-center rounded-xl bg-primary/10 text-primary"><FileText class="size-6" /></div><p class="font-semibold">No materials added yet</p><p class="mt-1 text-sm text-muted-foreground">Add a material to define its loading points, delivery destinations and commercial rates.</p><Button class="mt-5" @click="focusMaterialPicker"><Plus /> Add material</Button></div>
        <div v-for="material in form.materials" :key="material.material" class="rounded-lg border bg-background p-4"><div class="flex items-center justify-between gap-3"><button type="button" class="flex min-w-0 items-center gap-3 text-left" @click="toggleMaterial(material.material)"><span class="flex size-10 shrink-0 items-center justify-center rounded-lg bg-primary/10 text-primary"><FileText class="size-5" /></span><span class="min-w-0"><span class="block truncate font-bold">{{ material.material }}</span><span class="block text-xs text-muted-foreground">Cargo type · backend identifier</span></span></button><div class="flex items-center gap-1"><Button variant="ghost" size="icon" aria-label="Remove material" @click="removeMaterial(material.material)"><Trash2 /></Button><Button variant="ghost" size="icon" aria-label="Expand material" @click="toggleMaterial(material.material)"><ChevronUp v-if="expanded[material.material]" /><ChevronDown v-else /></Button></div></div><div v-if="expanded[material.material]" class="mt-4 grid gap-5 border-t pt-4 md:grid-cols-2"><div><p class="mb-2 text-xs font-bold uppercase tracking-wide text-muted-foreground">Loading points</p><LocationMultiSelect :model-value="selectedLocations(material.material, 'Loading')" :options="masters.locations" placeholder="Search loading points…" :disabled="!canEdit" @update:model-value="setLocations(material.material, 'Loading', $event)" @search="searchLocations($event, 'Loading')" /></div><div><p class="mb-2 text-xs font-bold uppercase tracking-wide text-muted-foreground">Delivery destinations</p><LocationMultiSelect :model-value="selectedLocations(material.material, 'Destination')" :options="masters.locations" placeholder="Search delivery destinations…" :disabled="!canEdit" @update:model-value="setLocations(material.material, 'Destination', $event)" @search="searchLocations($event, 'Destination')" /></div></div></div>
      </section>
      <section class="rounded-xl border bg-card p-5 shadow-sm"><div class="mb-4 flex items-start justify-between"><div><h2 class="text-lg font-bold">Commercial rate schedule</h2><p class="text-sm text-muted-foreground">Rates unlock when every material has loading and destination coverage.</p></div><Button variant="outline" :disabled="!completion.ready" @click="addRate"><Plus /> Add rate</Button></div><div v-if="!completion.ready" class="flex items-center gap-2 rounded-lg bg-blue-50 p-3 text-sm text-blue-700"><Info class="size-4 shrink-0" />Complete loading points and destinations above to add commercial rates.</div><div v-else class="overflow-x-auto"><table class="w-full min-w-[980px] text-sm"><thead><tr class="border-b text-left text-xs uppercase text-muted-foreground"><th class="p-2">Material</th><th class="p-2">Loading point</th><th class="p-2">Destination</th><th class="p-2">Rate / TON (AED)</th><th class="p-2">Effective from</th><th class="p-2">Effective to</th><th /></tr></thead><tbody><tr v-for="(row, index) in form.rates" :key="index" class="border-b align-top"><td class="p-2"><select v-model="row.material" class="control"><option v-for="item in form.materials" :key="item.material" :value="item.material">{{ item.material }}</option></select></td><td class="p-2"><select v-model="row.loading_location" class="control"><option value="">Select</option><option v-for="item in locationsForRate(row.material, 'Loading')" :key="item.location">{{ item.location }}</option></select></td><td class="p-2"><select v-model="row.unloading_location" class="control"><option value="">Select</option><option v-for="item in locationsForRate(row.material, 'Destination')" :key="item.location">{{ item.location }}</option></select></td><td class="p-2"><Input v-model="row.rate" type="number" min="0" step="0.001" /><p v-if="Number(row.rate) <= 0" class="mt-1 text-xs text-destructive">Positive rate required.</p></td><td class="p-2"><Input v-model="row.effective_from" type="date" /></td><td class="p-2"><Input v-model="row.effective_to" type="date" /><p v-if="rateOverlap(index)" class="mt-1 text-xs text-destructive">Period overlaps another route row.</p></td><td class="p-2"><Button variant="ghost" size="icon" aria-label="Remove rate" @click="removeRate(index)"><Trash2 /></Button></td></tr></tbody></table><p v-if="!form.rates.length" class="py-8 text-center text-sm text-muted-foreground">No commercial rates added yet.</p></div></section>
      <section class="rounded-xl border bg-card p-5 shadow-sm"><button type="button" class="flex w-full items-center justify-between text-left" @click="estimateOpen = !estimateOpen"><span><span class="block text-lg font-bold">Estimated Transportation Requirement</span><span class="block text-sm text-muted-foreground">Planning only — estimates never limit operational trips</span></span><ChevronUp v-if="estimateOpen" /><ChevronDown v-else /></button><div v-if="estimateOpen" class="mt-5 grid gap-4 border-t pt-5 sm:grid-cols-2"><label class="field">Estimated quantity<Input v-model="form.estimated_quantity" type="number" min="0" step="0.001" /></label><label class="field">Estimated trips<Input v-model="form.estimated_trips" type="number" min="0" step="1" /></label></div></section>
      <section class="rounded-xl border bg-card p-5 shadow-sm"><h2 class="text-lg font-bold">Customer approval record</h2><p class="mb-4 text-sm text-muted-foreground">Required by the backend before Frappe submission approves this quotation.</p><div class="grid gap-4 md:grid-cols-3"><label class="field">Approval date<Input v-model="form.customer_approval_date" type="date" /></label><label class="field">Approval reference<Input v-model="form.customer_approval_reference" placeholder="Optional" /></label><label class="field">Approval notes<textarea v-model="form.customer_approval_notes" class="control min-h-20" /></label></div></section>
    </fieldset>
    <div class="fixed inset-x-0 bottom-0 z-20 border-t bg-card/95 px-4 py-3 shadow-lg backdrop-blur sm:px-6 lg:left-64 lg:px-8 xl:left-72"><div class="mx-auto flex max-w-screen-2xl flex-wrap items-center justify-between gap-3"><p class="text-sm text-muted-foreground">{{ summary }}</p><div class="flex flex-wrap items-center gap-2"><Button variant="outline" :disabled="busy" @click="previewOpen = true"><Eye /> Preview</Button><Button v-if="canEdit" variant="outline" :disabled="busy" @click="save()"><Save /> Save draft</Button><Button v-if="canEdit && form.status === 'Draft'" :disabled="busy" @click="save(true)">Approve quotation</Button><Button variant="ghost" @click="router.push('/quotations')">Cancel</Button></div></div></div>
    <div v-if="previewOpen" class="fixed inset-0 z-50 flex items-center justify-center bg-foreground/40 p-4" role="dialog" aria-modal="true" aria-label="Quotation preview" @click.self="previewOpen = false"><div class="max-h-[90vh] w-full max-w-4xl overflow-auto rounded-xl bg-card p-6 shadow-xl"><div class="mb-5 flex items-start justify-between"><div><h2 class="text-xl font-bold">Quotation preview</h2><p class="text-sm text-muted-foreground">Unsaved values are included in this preview.</p></div><Button variant="ghost" size="icon" aria-label="Close preview" @click="previewOpen = false"><X /></Button></div><div class="grid gap-4 sm:grid-cols-3"><div><p class="label">Customer</p><p>{{ form.customer || '—' }}</p></div><div><p class="label">Quotation date</p><p>{{ form.quotation_date || '—' }}</p></div><div><p class="label">Valid until</p><p>{{ form.valid_until || '—' }}</p></div><div><p class="label">Service period</p><p>{{ form.service_period_from || '—' }} → {{ form.service_period_to || '—' }}</p></div><div><p class="label">Estimated quantity</p><p>{{ form.estimated_quantity || '—' }}</p></div><div><p class="label">Estimated trips</p><p>{{ form.estimated_trips || '—' }}</p></div></div><div class="mt-6"><p class="label">Materials and coverage</p><div v-for="material in form.materials" :key="material.material" class="mt-2 rounded-lg border p-3"><p class="font-semibold">{{ material.material }}</p><p class="text-sm text-muted-foreground">Loading: {{ selectedLocations(material.material, 'Loading').join(', ') || '—' }}</p><p class="text-sm text-muted-foreground">Destinations: {{ selectedLocations(material.material, 'Destination').join(', ') || '—' }}</p></div></div><div class="mt-6"><p class="label">Rates</p><p v-if="!form.rates.length" class="text-sm text-muted-foreground">No rates entered.</p><p v-for="row in form.rates" :key="`${row.material}-${row.loading_location}-${row.effective_from}`" class="border-b py-2 text-sm">{{ row.material }} · {{ row.loading_location }} → {{ row.unloading_location }} · AED {{ row.rate }} · {{ row.effective_from }} → {{ row.effective_to }}</p></div></div></div>
  </PageContainer>
</template>

<style scoped>
.field { @apply grid gap-1.5 text-sm font-semibold text-foreground; }
.control { @apply h-10 w-full rounded-md border border-input bg-background px-3 text-sm font-normal outline-none focus:ring-2 focus:ring-ring disabled:cursor-not-allowed disabled:opacity-50; }
textarea.control { @apply h-auto py-2; }
.label { @apply mb-1 text-xs font-bold uppercase tracking-wide text-muted-foreground; }
</style>
